'use strict';
// Модуль «Файловый менеджер»
/* ═════════════ Файловый менеджер ═════════════ */
function fsize(n){let h=7;for(const ch of n)h=(h*31+ch.charCodeAt(0))>>>0;return 38000+h%2400000}
function fmtSize(b){return b<1048576?Math.round(b/1024)+' КБ':(b/1048576).toFixed(1).replace('.',',')+' МБ'}
const fext=n=>{const i=n.lastIndexOf('.');return i>0?n.slice(i+1).toUpperCase():'ФАЙЛ'};
const FKIND={'Контрагент':'building','Отчёт':'file','Задача':'task','Поступление':'wallet','Оплата налога':'send','Разовая услуга':'coins','Проект':'briefcase','Загружен вручную':'upload'};
function allFiles(){const out=[];const vc=new Set(visCps(true,'files').map(c=>c.id));const add=(o)=>{o.size=o.manual&&o.manual.size!=null?o.manual.size:fsize(o.name);out.push(o)};
  CPS.forEach(c=>{if(!vc.has(c.id))return;(c.files||[]).forEach((n,i)=>add({id:`c${c.id}:${i}`,name:n,cp:c.id,kind:'Контрагент',src:(c.regFiles||[]).includes(n)?'Из свидетельства и выписки':'Карточка контрагента',date:(c._ua||c.start).slice(0,10),by:c._ub||c.resp,open:()=>openCp(c,'files'),rm:()=>fRm(c.files,n,'cp',c.id,c.id)}))});
  REPORTS.forEach(r=>{if(!vc.has(r.cp)||!r.files.length)return;r.files.forEach((n,i)=>add({id:`r${r.id}:${i}`,name:n,cp:r.cp,kind:'Отчёт',src:`${T[r.t].short} · ${r.plabel}`,date:r.subDate||TODAY,by:r.resp,open:()=>openReport(r),rm:()=>fRm(r.files,n,'r',r.id,r.cp)}))});
  if(feat('tasks'))TASKS.forEach(t=>{if(!t.file||(t.cp&&!vc.has(t.cp)))return;add({id:`t${t.id}`,name:t.file,cp:t.cp,kind:'Задача',src:t.title,date:t.doneAt||t.created,by:t.exec,open:()=>openTask(t),rm:()=>{const n=t.file;t.file='';log('t',t.id,'Удалён файл: '+n,t.cp)}})});
  if(taxVis())OPS.forEach(o=>{if(o.kind!=='pay'||!vc.has(o.cp))return;const r=REPORTS.find(y=>y.id===o.report);(o.files||[]).forEach((n,i)=>add({id:`x${o.id}:${i}`,name:n,cp:o.cp,kind:'Оплата налога',src:`Оплата ${r?T[r.t].short+' '+r.plabel:''} — ${som(o.amount)} от ${fmtD(o.date)}`,date:o.date,by:o.by,open:r?()=>openReport(r):null,rm:()=>fRm(o.files,n,r?'r':'cp',r?r.id:o.cp,o.cp)}))});
  if(taxVis())OPS.forEach(o=>{if(o.kind!=='in'||!vc.has(o.cp))return;(o.files||[]).forEach((n,i)=>add({id:`o${o.id}:${i}`,name:n,cp:o.cp,kind:'Поступление',src:`Поступление ${som(o.total??o.amount)} от ${fmtD(o.date)}`,date:o.date,by:o.by,open:()=>inCard(o),rm:()=>fRm(o.files,n,'cp',o.cp,o.cp)}))});
  SERVICES.forEach(s=>{if(!vc.has(s.cp))return;[...s.files,...s.pays.flatMap(p=>p.files||[])].forEach((n,i)=>add({id:`s${s.id}:${i}`,name:n,cp:s.cp,kind:'Разовая услуга',src:s.name,date:s.date,by:s.resp,open:()=>serviceCard(s),rm:()=>fRm(s.files.includes(n)?s.files:(s.pays.find(x=>(x.files||[]).includes(n))||{}).files,n,'s',s.id,s.cp)}))});
  PROJECTS.forEach(p=>{if(!vc.has(p.cp)||!projVisible(p))return;[...p.files,...p.pays.flatMap(x=>x.files||[])].forEach((n,i)=>add({id:`p${p.id}:${i}`,name:n,cp:p.cp,kind:'Проект',src:p.name,date:p.from,by:p.lead||p.resps[0],open:()=>openProject(p),rm:()=>fRm(p.files.includes(n)?p.files:(p.pays.find(x=>(x.files||[]).includes(n))||{}).files,n,'p',p.id,p.cp)}))});
  FILES.forEach(f=>{if(f.cp&&!vc.has(f.cp))return;add({id:f.id,name:f.name,cp:f.cp,kind:'Загружен вручную',src:'Загружен вручную',date:f.at,by:f.by,manual:f,open:null})});
  return out}
// Удаление прикреплённого файла из списка модуля: файл пропадает из записи, удаление пишется в её историю
function fRm(arr,n,ent,id,cp){if(!arr)return;const i=arr.indexOf(n);if(i>=0)arr.splice(i,1);log(ent,id,'Удалён файл: '+n,cp)}
const FKIND_L={'Загружен вручную':'Загружено вручную','Контрагент':'Карточки контрагентов','Отчёт':'К отчётам','Задача':'К задачам','Поступление':'К поступлениям','Оплата налога':'К оплатам налогов','Разовая услуга':'К разовым услугам','Проект':'К проектам'};
function filesAdd(){return can('filesUpload')?[{label:'Загрузить файл',icon:'upload',run:()=>uploadDlg()}]:[]}
function renderFiles(body,tab,fresh){const all=allFiles();
  body.innerHTML=`<div class="plates">${Object.keys(FKIND).filter(k=>k==='Загружен вручную'||all.some(f=>f.kind===k)).map(k=>plate({id:k,icon:FKIND[k],color:k==='Загружен вручную'?'purple':'blue',label:FKIND_L[k]||k,value:all.filter(f=>f.kind===k).length})).join('')}</div><div id="flg"></div>`;
  body.querySelector('.plates').onclick=e=>{const b=e.target.closest('[data-plate]');if(!b)return;const g=GS.files;if(!g)return;g.filters={kind:{type:'enum',vals:[b.dataset.plate]}};g.page=0;renderPage()};
  grid($('#flg',body),{id:'files',audit:x=>x.manual||{_ca:x.date+' 09:00',_cb:x.by},cols:[
    {key:'name',label:'Файл',type:'text',w:320,val:f=>f.name,html:f=>`${ic('file','sm')} <span class="strong">${esc(f.name)}</span>`},
    {key:'ext',label:'Тип',type:'enum',w:80,val:f=>fext(f.name),hide:true},
    {key:'kind',label:'Откуда',type:'enum',w:170,hide:true,val:f=>f.kind,html:f=>`<span class="tag">${ic(FKIND[f.kind],'sm')} ${esc(f.kind)}</span>`},
    {key:'src',label:'Источник',type:'text',w:280,val:f=>f.src},
    {key:'cp',label:'Контрагент',type:'enum',w:210,val:f=>f.cp?CPM[f.cp].name:'',html:f=>f.cp?esc(CPM[f.cp].name):'<span class="faint">общий файл</span>'},
    {key:'date',label:'Дата',type:'date',w:110,val:f=>f.date},
    {key:'size',label:'Размер',type:'int',w:100,num:true,val:f=>f.size,html:f=>fmtSize(f.size),hide:true},
    {key:'by',label:'Загрузил',type:'enum',w:130,val:f=>whoName(f.by)},
    {key:'desc',label:'Описание',type:'text',w:220,val:f=>f.manual?f.manual.note||'':'',hide:true}],
    rows:allFiles,title:'name',noun:['файл','файла','файлов'],sort:{key:'date',dir:-1},preset:S.preset,simulateLoad:fresh,open:openFile,
    actions:f=>[{label:'Открыть',icon:'eye',run:()=>openFile(f)},{label:'Скачать',icon:'download',run:()=>toast('Скачивание: '+f.name,'download')},...(f.open?[{label:'Перейти к источнику',icon:FKIND[f.kind],run:f.open}]:[]),...(f.manual?[{sep:true},{label:'Удалить',icon:'trash',danger:true,disabled:!(can('filesDelete')||f.manual.by===S.me&&diffDays(TODAY,(f.manual.at||'').slice(0,10))<=1),reason:'Нужно право «Удалять файлы»: свой файл можно удалить без права в течение суток',run:()=>confirmDlg({title:`Удалить «${esc(f.name)}»?`,text:'Файл загружен вручную и нигде больше не прикреплён.',ok:'Удалить',danger:true,run:()=>{FILES.splice(FILES.indexOf(f.manual),1);refreshAll();toast('Файл удалён')}})}]:f.rm?[{sep:true},{label:'Удалить',icon:'trash',danger:true,disabled:!fileDelOk(f.name),reason:'Нужно право «Удалять файлы»: свой файл можно удалить без права в течение суток',run:()=>confirmDlg({title:`Удалить «${esc(f.name)}»?`,text:`Файл пропадёт из записи «${esc(f.src)}» и из файлового менеджера. Удаление записывается в историю записи.`,ok:'Удалить',danger:true,run:()=>{f.rm();refreshAll();toast('Файл удалён','trash')}})}]:[])],
    empty:{icon:'folder',title:'Файлов пока нет',add:()=>uploadDlg()}});
}
function openFile(f){if(!f)return;openModal({size:'mid',render:()=>({title:esc(f.name),sub:`${esc(f.kind)} · ${esc(f.src)}`,body:`<div class="box" style="align-items:center;justify-content:center;min-height:180px;text-align:center"><span style="transform:scale(2.2);display:inline-block;color:var(--muted)">${ic('file')}</span><b style="margin-top:12px">${fext(f.name)} · ${fmtSize(f.size)}</b><span class="hint">Предпросмотр PDF и картинок появится в рабочей версии</span></div>
  <div class="box"><div class="kv"><div><span class="k">Откуда</span><span class="v">${esc(f.kind)}</span></div><div><span class="k">Источник</span><span class="v">${esc(f.src)}</span></div><div><span class="k">Контрагент</span><span class="v">${f.cp?esc(CPM[f.cp].name):'общий файл организации'}</span></div><div><span class="k">Загрузил</span><span class="v">${esc(whoName(f.by)||'—')}, ${fmtD(f.date)}</span></div></div></div>`,
  foot:`<button class="btn" id="fo-dl">${ic('download','sm')}Скачать</button><div class="grow"></div>${f.open?`<button class="btn cta" id="fo-src">${ic(FKIND[f.kind],'sm')}Перейти к источнику</button>`:'<button class="btn cta" data-close>Готово</button>'}`,
  mount(el,m){$('#fo-dl',el).onclick=()=>toast('Скачивание: '+f.name,'download');if($('#fo-src',el))$('#fo-src',el).onclick=()=>{m.close();f.open()}}})})}
function uploadDlg(c0){openModal({form:true,render:()=>({title:'Загрузить файл',sub:'Файл появится в файловом менеджере с источником «Загружен вручную»',body:`<div class="form">${fld('Файлы',`<input class="inp" type="file" id="up-f" multiple>`,{req:true,full:true,id:'up-f'})}${fld('Контрагент',sel('up-cp',[['','— общий файл организации —'],...visCps(false,'files').map(c=>[c.id,c.name])],c0?c0.id:''),{id:'up-cp',hint:'Файл контрагента виден и в его карточке'})}${fld('Комментарий',inp('up-note',''),{full:true,id:'up-note'})}</div>`,
  foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="up-ok">Загрузить</button>',
  mount(el,m){$('#up-ok',el).onclick=()=>{const fs=[...$('#up-f',el).files];if(!setErr(el,'up-f',fs.length?'':'Выберите хотя бы один файл'))return;const big=fs.filter(x=>x.size>20*1048576);if(!setErr(el,'up-f',big.length?`Файл больше 20 МБ: ${big.map(x=>x.name).join(', ')}`:''))return;const cp=+val(el,'up-cp')||null;fs.forEach(x=>FILES.push(born({id:'m'+(FILES.length+1)+'u'+Date.now()%10000,name:x.name,size:x.size,cp,by:S.me,at:TODAY,note:val(el,'up-note')})));if(cp)log('cp',cp,'Загружены файлы: '+fs.map(x=>x.name).join(', '),cp);m.close();refreshAll();toast(`Загружено: ${fs.length}`,'upload')}}})})}

